    BusLifeCycleListener listener = mock(BusLifeCycleListener.class);
    lifeCycleManager.registerLifeCycleListener(listener);
    bus.shutdown(true);
    verify(listener).preShutdown();
    verify(listener).postShutdown();
    bus.shutdown(true);
}

