    Set<Class<?>> loadedClasses = wrapperClassLoader.generate(factory, interfaceInfo, false);
    assertEquals(2, loadedClasses.size());
    // The class names must match, but the classes themselves are different because they were loaded
    // using different class loaders
    final List<String> generatedClassNames = generatedClasses.stream().map(Class::getName).collect(Collectors.toList());
    final List<String> loadedClassNames = loadedClasses.stream().map(Class::getName).collect(Collectors.toList());
    assertEquals(generatedClassNames, loadedClassNames);
    return loadedClassNames;
}

