    Map<String, List<String>> headers = CastUtils.cast((Map<?, ?>) message.get(Message.PROTOCOL_HEADERS));
    assertNotNull("expected request headers set", headers);
    assertTrue("expected output stream format", message.getContentFormats().contains(OutputStream.class));
    when(connection.getRequestMethod()).thenReturn(method);
    if (!"GET".equals(method)) {
        os = mock(OutputStream.class);
        when(connection.getOutputStream()).thenReturn(os);
    }
    message.put(HTTPConduit.KEY_HTTP_CONNECTION, connection);
    if (expectHeaders) {
        doNothing().when(connection).setRequestProperty(eq("Authorization"), eq("Basic Qko6dmFsdWU="));
        doNothing().when(connection).setRequestProperty(eq("Content-Type"), eq("text/xml;charset=utf8"));
        doNothing().when(connection).setRequestProperty(eq("Accept"), eq("text/xml;charset=utf8,text/plain"));
    }
    when(connection.getRequestProperties()).thenReturn(new HashMap<String, List<String>>());
    AbstractThresholdOutputStream wrappedOS = (AbstractThresholdOutputStream) message.getContent(OutputStream.class);
    assertNotNull("expected output stream", wrappedOS);
    wrappedOS.write(PAYLOAD.getBytes());
    wrappedOS.unBuffer();
    return wrappedOS;
}

