private void verifyBackChannelSend(Conduit backChannel, Message outMsg, int status, boolean oneway) throws Exception {
    outMsg.getExchange().setOneWay(oneway);
    assertTrue("unexpected back channel type", backChannel instanceof UndertowHTTPDestination.BackChannelConduit);
    assertTrue("unexpected content formats", outMsg.getContentFormats().contains(OutputStream.class));
    OutputStream responseOS = outMsg.getContent(OutputStream.class);
    assertNotNull("expected output stream", responseOS);
    assertTrue("unexpected output stream type", responseOS instanceof AbstractWrappedOutputStream);
    outMsg.put(Message.RESPONSE_CODE, status);
    responseOS.write(PAYLOAD.getBytes());
    setUpResponseHeaders(outMsg);
    responseOS.flush();
    assertEquals("unexpected status", status, response.getStatus());
    verifyResponseHeaders(outMsg);
    if (oneway) {
        assertNull("unexpected HTTP response", outMsg.get(AbstractHTTPDestination.HTTP_RESPONSE));
    } else {
        assertNotNull("expected HTTP response", outMsg.get(AbstractHTTPDestination.HTTP_RESPONSE));
        responseOS.close();
    }
}

